import React, { useState } from "react";

const placeData = {
  varanasi: [
    "Dashashwamedh Ghat",
    "Kashi Vishwanath Temple",
    "Sarnath",
    "Manikarnika Ghat",
    "Banaras Hindu University",
  ],
  jaipur: [
    "Hawa Mahal",
    "Amber Fort",
    "City Palace",
    "Jantar Mantar",
    "Nahargarh Fort",
  ],
  udaipur: [
    "Lake Pichola",
    "City Palace",
    "Jag Mandir",
    "Fateh Sagar Lake",
    "Sajjangarh Fort",
  ],
  delhi: [
    "India Gate",
    "Qutub Minar",
    "Red Fort",
    "Lotus Temple",
    "Humayun’s Tomb",
  ],
};

function RoutePlanner({ tourist, onProceed }) {
  const cityKey = tourist.city?.toLowerCase();
  const places = placeData[cityKey] || ["No data available for this city yet."];

  return (
    <div className="min-h-screen bg-gradient-to-br from-orange-50 to-yellow-100 flex items-center justify-center">
      <div className="bg-white/90 p-8 rounded-2xl shadow-xl max-w-xl w-full backdrop-blur-md text-center">
        <h1 className="text-3xl font-bold text-orange-600 mb-4">🗺️ Route Planner</h1>
        <p className="text-lg text-gray-700 mb-6">
          Welcome, <span className="font-semibold">{tourist.name}</span>!<br />
          Here are the must-visit places in <b>{tourist.city}</b>.
        </p>
        <ul className="text-left mb-8 space-y-2">
          {places.map((place, index) => (
            <li
              key={index}
              className="bg-orange-100 px-4 py-2 rounded-lg shadow-sm hover:bg-orange-200 transition"
            >
              {index + 1}. {place}
            </li>
          ))}
        </ul>
        <button
          onClick={onProceed}
          className="bg-orange-500 hover:bg-orange-600 text-white px-6 py-3 rounded-lg font-semibold transition"
        >
          ✅ Proceed to Safety Check
        </button>
      </div>
    </div>
  );
}

export default RoutePlanner;
